import { describe, expect, it } from "vitest";
import { romanize } from "./romanize";
import { CURATED_CARDS } from "./vocabulary";

/**
 * romanize() is a test-time and import-time tool, not a runtime one: the app
 * never calls it. The Essential 600 deck's stored romanization is generated by
 * it, and data.test.ts lints that every imported card still matches it and that
 * every curated (hand-written) card agrees with it ignoring case and spacing.
 * These cases pin the function itself against the official Revised Romanization
 * of Korean (National Institute of Korean Language, Chapter 3 "Transcription
 * Rules"), which is what a learner reads under the Korean.
 */

type Case = [hangul: string, romanization: string];

function expectAll(cases: Case[]) {
  for (const [hangul, expected] of cases) {
    expect(romanize(hangul), hangul).toBe(expected);
  }
}

describe("romanize: plain syllables (RR ch.2 vowels and consonants)", () => {
  it("writes simple and diphthong vowels (RR ch.2 sec.1)", () => {
    expectAll([
      ["아이", "ai"],
      ["왜", "wae"],
      ["의사", "uisa"],
      ["여우", "yeou"],
      ["어머니", "eomeoni"],
      ["오리", "ori"],
    ]);
  });

  it("writes initial consonants, including tense and aspirated (RR ch.2 sec.2)", () => {
    expectAll([
      ["가방", "gabang"],
      ["꽃", "kkot"],
      ["토끼", "tokki"],
      ["파도", "pado"],
      ["짜장", "jjajang"],
      ["차", "cha"],
    ]);
  });

  it("writes final consonants by their neutralised sound (RR ch.2 sec.2)", () => {
    expectAll([
      ["밥", "bap"],
      ["꽃", "kkot"],
      ["부엌", "bueok"],
      ["값", "gap"],
      ["닭", "dak"],
      ["밖", "bak"],
    ]);
  });
});

describe("romanize: liaison before a vowel (RR ch.3 art.3)", () => {
  it("moves a final consonant onto the next syllable: 한국어 → hangugeo", () => {
    expectAll([
      ["한국어", "hangugeo"],
      ["음악", "eumak"],
      ["집에", "jibe"],
      ["옷이", "osi"],
    ]);
  });

  it("splits a compound final: the second consonant moves, 닭이 → dalgi", () => {
    expectAll([
      ["닭이", "dalgi"],
      ["읽어요", "ilgeoyo"],
      ["젊어요", "jeolmeoyo"],
    ]);
  });

  it("does not move a final ㅇ: 강아지 → gangaji", () => {
    expectAll([
      ["강아지", "gangaji"],
      ["고양이", "goyangi"],
    ]);
  });

  it("drops a silent ㅎ before a vowel: 좋아요 → joayo", () => {
    expectAll([
      ["좋아요", "joayo"],
      ["괜찮아요", "gwaenchanayo"],
      ["싫어요", "sireoyo"],
    ]);
  });
});

describe("romanize: sound changes RR transcribes (RR ch.3 art.3)", () => {
  it("writes ㅎ aspiration with ㄱ/ㄷ/ㅈ: 좋다 → jota (art.3 item 3)", () => {
    expectAll([
      ["좋다", "jota"],
      ["좋고", "joko"],
      ["놓다", "nota"],
      ["낳지", "nachi"],
    ]);
  });

  it("writes palatalization of ㄷ/ㅌ before 이: 같이 → gachi, 굳이 → guji (art.3 item 2)", () => {
    expectAll([
      ["같이", "gachi"],
      ["굳이", "guji"],
      ["해돋이", "haedoji"],
    ]);
  });

  it("writes nasal assimilation before ㄴ/ㅁ: 국물 → gungmul, 감사합니다 → gamsahamnida (art.3 item 1)", () => {
    expectAll([
      ["국물", "gungmul"],
      ["감사합니다", "gamsahamnida"],
      ["합니다", "hamnida"],
      ["먹는", "meongneun"],
      ["백마", "baengma"],
      ["십만", "simman"],
    ]);
  });

  it("writes ㄹ after ㄴ/ㅁ/ㅇ as n: 종로 → jongno, 신문로 → sinmunno (art.3 item 1)", () => {
    expectAll([
      ["종로", "jongno"],
      ["신문로", "sinmunno"],
      ["음료수", "eumnyosu"],
    ]);
  });

  it("writes ㄹ as r before a vowel and l elsewhere (art.3 item 1 and art.8)", () => {
    expectAll([
      ["오리", "ori"],
      ["달", "dal"],
      ["별로", "byeollo"],
      ["얼마", "eolma"],
    ]);
  });

  it("does NOT write tensification: 학교 → hakgyo (art.3 item 5)", () => {
    expectAll([
      ["학교", "hakgyo"],
      ["낙동강", "nakdonggang"],
      ["압구정", "apgujeong"],
      ["샛별", "saetbyeol"],
      ["죽변", "jukbyeon"],
    ]);
  });

  it("keeps ㄱ/ㅂ + ㅎ apart when RR says the ㅎ is not merged: 묵호 → mukho, 집현전 → jiphyeonjeon (art.3 item 3 note)", () => {
    expectAll([
      ["묵호", "mukho"],
      ["집현전", "jiphyeonjeon"],
    ]);
  });
});

describe("romanize: input handling", () => {
  it("romanizes each word of a phrase and keeps the spaces", () => {
    expect(romanize("뭘 먹고 싶어요")).toBe("mwol meokgo sipeoyo");
  });

  it("passes punctuation through and trims the ends", () => {
    expect(romanize("  어디입니까?  ")).toBe("eodiimnikka?");
  });

  it("uses the lexical exception for 나뭇잎 (ㄴ insertion, RR art.1: write the pronunciation)", () => {
    expect(romanize("나뭇잎")).toBe("namunnip");
  });
});

describe("romanize: deck words checked against RR", () => {
  // Expected values are written from RR, not read from the deck.
  const deckWords: [id: string, front: string, rr: string][] = [
    ["surv_001", "안녕하세요", "annyeonghaseyo"],
    ["surv_002", "감사합니다", "gamsahamnida"],
    ["surv_003", "죄송합니다", "joesonghamnida"],
    ["surv_006", "모르겠습니다", "moreugetseumnida"],
    ["num_007", "일곱", "ilgop"],
    ["num_008", "여덟", "yeodeol"],
    ["food_009", "김밥", "gimbap"],
    ["food_012", "떡볶이", "tteokbokki"],
  ];

  for (const [id, front, rr] of deckWords) {
    it(`${id} ${front}: stored romanization and romanize() both equal ${rr}`, () => {
      const card = CURATED_CARDS.find(c => c.id === id);
      expect(card, id).toBeDefined();
      expect(card!.front).toBe(front);
      expect(card!.romanization).toBe(rr);
      expect(romanize(front)).toBe(rr);
    });
  }
});
